  placement="left"
  align="bottom"
  haptics
  value={SECTIONS[page]?.id}
  onValueChange={(next) => {
    const index = SECTIONS.findIndex((s) => s.id === next);
    if (index < 0 || !pageHeight) return;
    setPage(index);
    scroller.current?.scrollTo({ y: index * pageHeight, animated: true });
  }}
>
  {/* …bars and items… */}
</SectionRail>

